)","summary":"Emana uma aura radiante de 9 metros que causa dano radiante a inimigos e concede vantagem contra magias.","content":"Emana uma aura radiante de 9 metros que causa dano radiante a inimigos e concede vantagem contra magias.","kind":"feature","class_slug":"paladin","subclass_slug":"juramento-da-devocao","level":20,"sheet":"Características por Subclasse","row":176,"grant":"subclass"},{"slug":"paladin-juramento-da-gloria-3-atleta-heroico-smite-inspirador","name":"Atleta Heroico & Smite Inspirador (Juramento da Glória)","summary":"Ganha vantagem em testes de Atletismo/Acrobacia e distribui PVs temporários a aliados após aplicar Punição Divina.","content":"Ganha vantagem em testes de Atletismo/Acrobacia e distribui PVs temporários a aliados após aplicar Punição Divina.","kind":"feature","class_slug":"paladin","subclass_slug":"juramento-da-gloria","level":3,"sheet":"Características por Subclasse","row":177,"grant":"subclass"},{"slug":"paladin-juramento-da-gloria-7-aura-de-alacridade","name":"Aura de Alacridade (Juramento da Glória)","summary":"Aumenta o deslocamento de todos os aliados que começarem o turno próximo a você.","content":"Aumenta o deslocamento de todos os aliados que começarem o turno próximo a você.","kind":"feature","class_slug":"paladin","subclass_slug":"juramento-da-gloria","level":7,"sheet":"Características por Subclasse","row":178,"grant":"subclass"},{"slug":"paladin-juramento-da-gloria-15-escudo-glorioso","name":"Escudo Glorioso (Juramento da Glória)","summary":"Usa Reação para aumentar a CA de um aliado atingido por ataque e redirecionar o golpe.","content":"Usa Reação para aumentar a CA de um aliado atingido por ataque e redirecionar o golpe.","kind":"feature","class_slug":"paladin","subclass_slug":"juramento-da-gloria","level":15,"sheet":"Características por Subclasse","row":179,"grant":"subclass"},{"slug":"paladin-juramento-da-gloria-20-lenda-viva","name":"Lenda Viva (Juramento da Glória)","summary":"Transforma-se no auge do heroísmo: vantagem em todos os testes de atributo, falhas transformadas em acertos.","content":"Transforma-se no auge do heroísmo: vantagem em todos os testes de atributo, falhas transformadas em acertos.","kind":"feature","class_slug":"paladin","subclass_slug":"juramento-da-gloria","level":20,"sheet":"Características por Subclasse","row":180,"grant":"subclass"},{"slug":"paladin-juramento-de-vinganca-3-voto-de-inimizade-abjurar-inimigo","name":"Voto de Inimizade & Abjurar Inimigo (Juramento de Vingança)","summary":"Concede Vantagem em todas as jogadas de ataque contra um alvo específico por 1 minuto.","content":"Concede Vantagem em todas as jogadas de ataque contra um alvo específico por 1 minuto.","kind":"feature","class_slug":"paladin","subclass_slug":"juramento-de-vinganca","level":3,"sheet":"Características por Subclasse","row":181,"grant":"subclass"},{"slug":"paladin-juramento-de-vinganca-7-vingador-implacavel","name":"Vingador Implacável (Juramento de Vingança)","summary":"Move-se até metade do seu deslocamento como parte da reação ao realizar um ataque de oportunidade.","content":"Move-se até metade do seu deslocamento como parte da reação ao realizar um ataque de oportunidade.","kind":"feature","class_slug":"paladin","subclass_slug":"juramento-de-vinganca","level":7,"sheet":"Características por Subclasse","row":182,"grant":"subclass"},{"slug":"paladin-juramento-de-vinganca-15-almas-do-castigo","name":"Almas do Castigo (Juramento de Vingança)","summary":"Inimigos sob o efeito do seu Voto de Inimizade provocam ataques de oportunidade mesmo se usarem Desengajar.","content":"Inimigos sob o efeito do seu Voto de Inimizade provocam ataques de oportunidade mesmo se usarem Desengajar.","kind":"feature","class_slug":"paladin","subclass_slug":"juramento-de-vinganca","level":15,"sheet":"Características por Subclasse","row":183,"grant":"subclass"},{"slug":"paladin-juramento-de-vinganca-20-anjo-da-vinganca","name":"Anjo da Vingança (Juramento de Vingança)","summary":"Ganha asas assustadoras, deslocamento de voo de 18m e aura de pavor que imobiliza inimigos.","content":"Ganha asas assustadoras, deslocamento de voo de 18m e aura de pavor que imobiliza inimigos.","kind":"feature","class_slug":"paladin","subclass_slug":"juramento-de-vinganca","level":20,"sheet":"Características por Subclasse","row":184,"grant":"subclass"},{"slug":"paladin-juramento-dos-ancioes-3-ira-da-natureza-acorrentar-o-infiel","name":"Ira da Natureza & Acorrentar o Infiel (Juramento dos Anciões)","summary":"Convoca vinhas mágicas para imobilizar um inimigo com Canalizar Divindade.","content":"Convoca vinhas mágicas para imobilizar um inimigo com Canalizar Divindade.","kind":"feature","class_slug":"paladin","subclass_slug":"juramento-dos-ancioes","level":3,"sheet":"Características por Subclasse","row":185,"grant":"subclass"},{"slug":"paladin-juramento-dos-ancioes-7-aura-de-protecao-feerica","name":"Aura de Proteção Feérica (Juramento dos Anciões)","summary":"Você e aliados próximos recebem Resistência a todo o dano causado por magias.","content":"Você e aliados próximos recebem Resistência a todo o dano causado por magias.","kind":"feature","class_slug":"paladin","subclass_slug":"juramento-dos-ancioes","level":7,"sheet":"Características por Subclasse","row":186,"grant":"subclass"},{"slug":"paladin-juramento-dos-ancioes-15-sentinela-imortal","name":"Sentinela Imortal (Juramento dos Anciões)","summary":"Quando cair a 0 PV, pode optar por cair a 1 PV (uma vez por descanso longo) e não pode ser envelhecido por magia.","content":"Quando cair a 0 PV, pode optar por cair a 1 PV (uma vez por descanso longo) e não pode ser envelhecido por magia.","kind":"feature","class_slug":"paladin","subclass_slug":"juramento-dos-ancioes","level":15,"sheet":"Características por Subclasse","row":187,"grant":"subclass"},{"slug":"paladin-juramento-dos-ancioes-20-cavaleiro-primal","name":"Cavaleiro Primal (Juramento dos Anciões)","summary":"Transforma-se em um avatar da natureza: recupera PVs a cada turno e pode conjurar magias com Ação Bônus.","content":"Transforma-se em um avatar da natureza: recupera PVs a cada turno e pode conjurar magias com Ação Bônus.","kind":"feature","class_slug":"paladin","subclass_slug":"juramento-dos-ancioes","level":20,"sheet":"Características por Subclasse","row":188,"grant":"subclass"}]}$data$::jsonb;
 r jsonb; rid uuid; cid uuid; sid uuid; lid uuid; eid uuid;
 before_sheets text; before_links text; before_history text;
 source_label text := 'Planilha fornecida pelo usuário — referência PHB 2024';
 license_label text := 'Conteúdo fornecido pelo usuário; licença de redistribuição não informada';
begin
 perform pg_advisory_xact_lock(hashtext('grimorio-class-workbook-import'));
 select md5(coalesce(jsonb_agg(to_jsonb(t) order by id)::text,'')) into before_sheets from public.dnd_sheets t;
 select md5(coalesce(jsonb_agg(to_jsonb(t) order by id)::text,'')) into before_links from public.dnd_character_classes t;
 select md5(coalesce(jsonb_agg(to_jsonb(t) order by id)::text,'')) into before_history from public.dnd_level_ups t;
 insert into public.dnd_rulesets(slug,name,version,license)
 values ('phb-2024-workbook-v2','D&D 2024 — catálogo da planilha','2024-v2',license_label)
 on conflict(slug) do update set name=excluded.name,version=excluded.version,license=excluded.license
 returning id into rid;
 for r in select value from jsonb_array_elements(payload->'classes') loop
   -- Upgrade the bootstrap SRD catalog in place; retain foreign-key identities.
   update public.dnd_classes c set ruleset_id=rid
   where c.slug=r->>'slug' and c.ruleset_id=(select id from public.dnd_rulesets where slug='srd-5-2-1');
   insert into public.dnd_classes(ruleset_id,slug,name,hit_die,subclass_level)
   values(rid,r->>'slug',r->>'name',(r->>'hit_die')::smallint,3)
   on conflict(ruleset_id,slug) do update set name=excluded.name,hit_die=excluded.hit_die,subclass_level=excluded.subclass_level;
 end loop;
 for r in select value from jsonb_array_elements(payload->'subclasses') loop
   select id into strict cid from public.dnd_classes where ruleset_id=rid and slug=r->>'class_slug';
   insert into public.dnd_subclasses(class_id,slug,name) values(cid,r->>'slug',r->>'name')
   on conflict(class_id,slug) do update set name=excluded.name;
 end loop;
 for r in select value from jsonb_array_elements(payload->'levels') loop
   select id into strict cid from public.dnd_classes where ruleset_id=rid and slug=r->>'class_slug';
   insert into public.dnd_class_levels(class_id,level,proficiency_bonus)
   values(cid,(r->>'level')::smallint,(r->>'bonus')::smallint)
   on conflict(class_id,level) do update set proficiency_bonus=excluded.proficiency_bonus;
 end loop;
 for r in select value from jsonb_array_elements(payload->'entries') loop
   select id into strict cid from public.dnd_classes where ruleset_id=rid and slug=r->>'class_slug';
   sid := null;
   if r ? 'subclass_slug' then
     select id into strict sid from public.dnd_subclasses where class_id=cid and slug=r->>'subclass_slug';
   end if;
   insert into public.dnd_rule_entries(ruleset_id,kind,slug,name,summary,content,source_name,source_page,license,metadata)
   values(rid,r->>'kind',r->>'slug',r->>'name',r->>'summary',r->>'content',source_label,
     (r->>'sheet')||'!linha '||(r->>'row'),license_label,
     (r-'name'-'summary'-'content'-'kind'-'slug')||jsonb_build_object(
       'source_file',payload->>'source','source_sha256',payload->>'sha256',
       'class_id',cid,'subclass_id',sid,'automation','reference_only',
       'tags',jsonb_build_array(r->>'class_slug',r->>'subclass_slug'),
       'needs_review',position('舆' in (r->>'content'))>0))
   on conflict(ruleset_id,kind,slug) do update set
     name=excluded.name,summary=excluded.summary,content=excluded.content,
     source_name=excluded.source_name,source_page=excluded.source_page,license=excluded.license,metadata=excluded.metadata
   returning id into eid;
   if r->>'grant'='class' then
     select id into strict lid from public.dnd_class_levels where class_id=cid and level=(r->>'level')::smallint;
     insert into public.dnd_level_grants(class_level_id,rule_entry_id,grant_type,config)
     select lid,eid,'feature',jsonb_build_object('source_file',payload->>'source','automation','reference_only')
     where not exists(select 1 from public.dnd_level_grants where class_level_id=lid and rule_entry_id=eid);
   elsif r->>'grant'='subclass' then
     insert into public.dnd_subclass_levels(subclass_id,class_level) values(sid,(r->>'level')::smallint)
     on conflict(subclass_id,class_level) do update set class_level=excluded.class_level
     returning id into lid;
     insert into public.dnd_subclass_level_grants(subclass_level_id,rule_entry_id) values(lid,eid)
     on conflict(subclass_level_id,rule_entry_id) do nothing;
   end if;
 end loop;
 if (select count(*) from public.dnd_classes where ruleset_id=rid)<>12
 or (select count(*) from public.dnd_subclasses s join public.dnd_classes c on c.id=s.class_id where c.ruleset_id=rid)<>48
 or (select count(*) from public.dnd_class_levels l join public.dnd_classes c on c.id=l.class_id where c.ruleset_id=rid)<>240
 or (select count(*) from public.dnd_rule_entries where ruleset_id=rid)<>484
 or (select count(*) from public.dnd_level_grants g join public.dnd_rule_entries e on e.id=g.rule_entry_id where e.ruleset_id=rid)<>240
 or (select count(*) from public.dnd_subclass_level_grants g join public.dnd_rule_entries e on e.id=g.rule_entry_id where e.ruleset_id=rid)<>184
 then raise exception 'Contagens divergentes: importacao revertida'; end if;
 if before_sheets is distinct from (select md5(coalesce(jsonb_agg(to_jsonb(t) order by id)::text,'')) from public.dnd_sheets t)
 or before_links is distinct from (select md5(coalesce(jsonb_agg(to_jsonb(t) order by id)::text,'')) from public.dnd_character_classes t)
 or before_history is distinct from (select md5(coalesce(jsonb_agg(to_jsonb(t) order by id)::text,'')) from public.dnd_level_ups t)
 then raise exception 'Dados de personagens alterados: importacao revertida'; end if;
end;
$import$;
commit;
